head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = "ULDSTF30619.xml";
scwin.gIsurCd;
scwin.gChrgNm;
scwin.gComAbbrv;
scwin.gChrgTpNm;
scwin.gCOM_NM;
scwin.gSchDate;
scwin.procJob;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");

    //alert(url +"     =      "+ arr);		
    return (arr.length > 1 ? arr[1] : '');

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !정보--;
셋팅-- > function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd; // 법인코드				
    scwin.gCOM_NM = $c.frame.path("../").scwin.gComAbbrv; // 회사명
    scwin.gSchDate = $c.frame.path("../").scwin.gSchDate; // 조회일자

};
scwin.fn_Init = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    if (scwin.fn_GetProvider() == 'POPUPMODE') {
        //회사코드 셋팅
        txb_isur_cd.setValue(scwin.gIsurCd);
        txb_com_abbrv.setValue(scwin.gCOM_NM);
    }
};
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
};
scwin.fn_Search = function() {
    var SDate = edt_SDate.getValue();
    var basicVal = $c.ut.isDate(SDate);
    if (basicVal == false) {
        $c.win.alert("[조회기준일]의 날짜형식이 정확하지 않습니다.");
        return false;
    }
    $c.cm.ShowWin(grd_Grid);
    var url = "/ListedCompany.do?method=selectDutyEduPassStat";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&EDU_KIND_CD=" + $c.stf.getObjectValue(cmb_EDU_KIND_CD);
    url += "&BASE_DT=" + SDate;
    url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
    url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD);
    url += "&DUTY_EDU_YN=" + $c.stf.getObjectValue(cmb_DUTY_EDU_YN);
    url += "&YEAR_EDU_PASS_YN=" + $c.stf.getObjectValue(cmb_YEAR_EDU_PASS_YN);
    url += "&LNGTRM_CONTSVC_YN=" + $c.stf.getObjectValue(cmb_LNGTRM_CONTSVC_YN);
    url += "&EXCNT_DISCLS_CORP=" + $c.stf.getObjectValue(cmb_EXCNT_DISCLS_CORP);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};
scwin.getDisclsEduName = function(gubun) {
    dts_EduCrsNm.DataID = "/ListedCompany.do?method=getDisclsEduName" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R" + "&CHRG_TP_CD=" + gubun;
    dts_EduCrsNm.Reset();
};
scwin.fn_check = function() {
    var checkCnt = 0;
    for (var i = 1; i <= dts_MASTER.getTotalRow(); i++) {
        if (dts_MASTER.getCellData(i, "CHECK") == "T") {
            checkCnt++;
        }
    }
    if (checkCnt <= 0) {
        $c.win.alert("선택한 항목이 없습니다.");
        return false;
    }
    return true;
};



/* 
 *  2017.12.21
 *  이수여부(종합) 선택항목 저장/삭제
 */
scwin.fn_save = function() {
    //선택한 항목이 있는지 check
    if (scwin.fn_check() == true) {
        scwin.fn_SetHeader();
        var gCnt = 0;
        for (var i = 1, k = 1; i <= dts_MASTER.getTotalRow(); i++) {
            if (dts_MASTER.getCellData(i, "CHECK") == "T") {
                dts_UpdateList.insertRow();
                dts_UpdateList.setCellData(k, "ISUR_CD", dts_MASTER.getCellData(i, "ISUR_CD"));
                dts_UpdateList.setCellData(k, "CHRG_DESIGN_DD", dts_MASTER.getCellData(i, "CHRG_DESIGN_DD"));
                dts_UpdateList.setCellData(k, "CHRG_NM", dts_MASTER.getCellData(i, "CHRG_NM"));
                dts_UpdateList.setCellData(k, "CHRG_TP_CD", dts_MASTER.getCellData(i, "CHRG_TP_CD"));
                dts_UpdateList.setCellData(k, "NEW_EDU_COMPLT_YN", dts_MASTER.getCellData(i, "NEW_EDU_COMPLT_YN"));
                dts_UpdateList.setCellData(k, "REMK", "");
                dts_UpdateList.setCellData(k, "TRANSTR_EMP_NO", scwin.gEmpNo);
                k++;
                gCnt++;
            }
        }
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + gCnt + '건을 저장'))) return;
        scwin.procJob = "신규교육이수여부 저장";
        trs_save.Action = "/ListedCompany.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=modifyNewEduCompltYn";
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_UpdateList)";
        trs_save.Post();
    }
};
scwin.fn_SetHeader = function() {
    dts_UpdateList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NEW_EDU_COMPLT_YN_IN";
    dts_UpdateList.reset();
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_Search_onclick = function() {
    var SDate = edt_SDate.getValue();
    if (SDate > '20111231') {
        scwin.fn_Search();
    } else {
        $c.win.alert("조회기준일은 2012년 1월 1일 부터 선택하세요.");
    }
};
scwin.dts_MASTER_OnFail = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadError = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_MASTER.removeAll();
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnClick = function(row, colid) {

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.gIsurCd = dts_MASTER.getCellData(eval(row), "ISUR_CD");
    scwin.gChrgNm = dts_MASTER.getCellData(eval(row), "CHRG_NM");
    scwin.gComAbbrv = dts_MASTER.getCellData(eval(row), "COM_ABBRV");
    scwin.gChrgTpNm = dts_MASTER.getCellData(eval(row), "CHRG_TP_NM");
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "LNGTRM_CONTSVC_YN") {
        await $c.frame.CreateDialogFrame("wndDiscls", "/issueinfo/ULDSTF30632.gfm", "장기근속자 해당여부 관리", 300, 220, 610, 340, "window");
    } else if (colid == "YEAR_REAL_PASS_TIME") {
        $c.frame.path("/top").WinOpen("ULDSTF30618_REAL", "/issueinfo/ULDSTF30618.gfm?ISUR_CD=" + scwin.gIsurCd + "&COM_NM=" + scwin.gComAbbrv + "&" + frame.FrameID, "공시담당자등 교육참가현황(유)", 1300, 810);
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.cmb_EDU_KIND_CD_OnSelChange = function() {
    gubun = $c.cp.valueOfIndex(cmb_EDU_KIND_CD, "VALUE", cmb_EDU_KIND_CD.getSelectedIndex());

    //if(gubun != '')  {
    //	getDisclsEduName(gubun);
    //}	

};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "공시교육참가현황", "", "8");
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.trs_save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_Search();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_FORM_U221_onclick = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF30619_POP", "/issueinfo/ULDSTF30619_POP.gfm", "의무이수기간 기준", 150, 50, 582, 500, "window");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    fn_GetParentValue();
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Init();
    scwin.fn_Search();
};
scwin.btn_FORM_U1_onclick = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF37212", "/dsclmgt/ULDSTF37212.gfm", "적출기준조회", 150, 50, 582, 600, "window");
};
